import type { ReactNode } from 'react';

// We'll create a simple markdown renderer for now.
// In a real app, you might use a library like react-markdown.
function MarkdownRenderer({ children }: { children: string }) {
  // For simplicity, we just return the text as is.
  // You can replace this with a proper markdown renderer.
  return <div className="prose prose-sm max-w-none">{children}</div>;
}

interface MessageListProps {
  messages: Array<{ id: number; text: string; isUser: boolean }>;
  isLoading: boolean;
}

export const MessageList = ({ messages, isLoading }: MessageListProps) => {
  return (
    <>
      {messages.map((message) => (
        <div key={message.id} className="flex flex-col">
          <div
            className={`max-w-[80%] ${
              message.isUser ? 'ml-auto bg-blue-500 text-white' : 'mr-auto bg-gray-200 text-gray-800'
            } rounded-lg px-4 py-2`}
          >
            <MarkdownRenderer>{message.text}</MarkdownRenderer>
          </div>
          {message.isUser && (
            <div className="text-xs text-gray-500 mt-1">
              {/* Timestamp or status */}
            </div>
          )}
        </div>
      ))}
      {isLoading && (
        <div className="flex items-center justify-center py-4">
          <div className="flex items-center space-x-2">
            <div className="h-3 w-3 rounded-full bg-gray-400 animate-pulse"></div>
            <div className="h-3 w-3 rounded-full bg-gray-400 animate-pulse"></div>
            <div className="h-3 w-3 rounded-full bg-gray-400 animate-pulse"></div>
          </div>
          <span className="text-gray-500">Thinking...</span>
        </div>
      )}
    </>
  );
};

import { useState } from 'react';
import { FiSend } from 'react-icons/fi';

interface PromptInputProps {
  onSend: (text: string) => void;
  isLoading: boolean;
}

export default function PromptInput({ onSend, isLoading }: PromptInputProps) {
  const [text, setText] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (text.trim() && !isLoading) {
      onSend(text);
      setText('');
    }
  };

  return (
    <form onSubmit={handleSubmit} className="flex items-center px-6 py-4 bg-white border-t">
      <input
        value={text}
        onChange={(e) => setText(e.target.value)}
        placeholder="Type a message..."
        className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:opacity-50"
        disabled={isLoading}
      />
      <button
        type="submit"
        disabled={isLoading || !text.trim()}
        className="ml-2 px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 disabled:opacity-50 transition-colors"
      >
        <FiSend className="h-4 w-4" />
      </button>
    </form>
  );
}

import { FiMessageSquare, FiWifiOff } from 'react-icons/fi';

export default function EmptyState() {
  return (
    <div className="flex flex-col items-center justify-center py-12 text-center">
      <FiMessageSquare className="h-12 w-12 text-gray-400 mb-4" />
      <h2 className="text-xl font-semibold text-gray-800 mb-2">Start a conversation</h2>
      <p className="text-gray-600 mb-6">
        Ask me anything and I'll do my best to help.
      </p>
      <div className="flex items-center space-x-3 text-sm text-gray-500">
        <FiWifiOff className="h-4 w-4" />
        <span>Offline mode</span>
      </div>
    </div>
  );
}

